void generate_maze(Maze* maze, int width, int height) {
    SDL_Maze *maze_gen;
    maze_gen = SDL_CreateMaze(width, height);
    SDL_GenerateMaze(maze_gen);

    maze->width = width;
    maze->height = height;
    maze->walls = (int**) malloc(height * sizeof(int*));

