9. Gérer les interactions du serpent :

Créer une fonction pour gérer les interactions du serpent, telle que la direction et la collision avec le mur :

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define WIDTH 640
#define HEIGHT 480

typedef struct {
    int x, y;
} Point;

typedef struct {
    Point* body;
    int length;
    int direction;
} Snake;

void move_snake(Snake* snake, int width, int height) {
    Point* new_body = (Point*) malloc((snake->length + 1) * sizeof(Point));
    memcpy(new_body, snake->body, snake->length * sizeof(Point));

    switch (snake->direction) {
        case 0: // Droite
            new_body[snake->length].x = snake->body[snake->length - 1].x + 20;
            new_body[snake->length].y = snake->body[snake->length - 1].y;
            break;
        case 1: // Gauche
            new_body[snake->length].x = snake->body[snake->length - 1].x - 20;
            new_body[snake->length].y = snake->body[snake->length - 1].y;
            break;
        case 2: // Bas
            new_body[snake->length].x = snake->body[snake->length - 1].x;
            new_body[snake->length].y = snake->body[snake->length - 1].y + 20;
            break;
        case 3: // Haut
            new_body[snake->length].x = snake->body[snake->length - 1].x;
            new_body[snake->length].y = snake->body[snake->length - 1].y - 20;
            break;
    }

    free(snake->body);
    snake->body = new_body;
    snake->length++;

    if (snake->length == maze.width * maze.height / 20) {
        score++;
        snake->direction = rand() % 4;
    }
}

int check_collision(Snake* snake, Maze* maze) {
    for (int I = 1; I < snake->length; i++) {
        if (snake->body[i].x == snake->body[0].x && snake->body[i].y == snake->body[0].y) {
            return 1;
        }
    }

    for (int I = 0; I < maze->height; i++) {
        for (int j = 0; j < maze->width; j++) {
            if (maze->walls[i][j] == SDL_MAZE_WALL && snake->body[0].x / 20 == j && snake->body[0].y / 20 == i) {
                return 1;
            }
        }
    }

    return 0;
}
```

10. Boucle de jeu :

Créer une fonction pour exécuter le jeu en boucle :

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#include "SDL2/SDL.h"

#define WIDTH 640
#define HEIGHT 480

typedef struct {
    int x, y;
} Point;

typedef struct {
    Point* body;
    int length;
    int direction;
} Snake;

typedef struct {
    int width, height;
    int** walls;
} Maze;

Snake snake;
Maze maze;
int score;

void play_game() {
    SDL_Event event;

    Snake snake = generate_snake(WIDTH / 2, HEIGHT / 2);
    generate_maze(&maze, WIDTH / 20, HEIGHT / 20);

    while (1) {
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                exit(0);
            }

            if (event.type == SDL_KEYDOWN) {
                switch (event.key.keysym.sym) {
                    case SDLK_RIGHT:
                        snake.direction = 0;
                        break;
                    case SDLK_LEFT:
                        snake.direction = 1;
                        break;
                    case SDLK_DOWN:
                        snake.direction = 2;
                        break;
                    case SDLK_UP:
                        snake.direction = 3;
                        break;
                }
            }
        }

        move_snake(&snake, maze.width, maze.height);

        if (check_collision(&snake, &maze)) {
            printf("Game Over!\n");
            exit(0);
        }

        render_scene(window, renderer, snake, maze);

        SDL_Delay(100);
    }
}

int main() {
    SDL_Window* window = init_sdl(WIDTH, HEIGHT);
    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);

    snake.head_texture = load_image("head.bmp");
    snake.body_texture = load_image("body.bmp");
    maze.wall_texture = load_image("wall.bmp");

    play_game();

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();

    return 0;
}
```

